def apply_fn_to_grad(grad_fn):
  """Applies a scalar `grad_fn` function to the gradient of the input."""

  @jax.custom_vjp
  def fn_out(x):
    return x

  fn_out.defvjp(lambda x: (x, None), lambda _, y: (grad_fn(y),))
